<verify>
<verified claim="mcm_..." files="path/a.ts,path/b.ts"/>
<update claim="mcm_..." files="path/c.ts">corrected present-tense content</update>
<archive claim="mcm_..." reason="specific evidence the code contradicts it"/>
</verify>

