    boundarySnapshot: providedBoundarySnapshot,
    refreshBoundarySnapshot,
    currentContextLimit,
    historianTimeoutMs = DEFAULT_HISTORIAN_TIMEOUT_MS2,
    signal,
    retryBackoffMs,
    twoPass,
    thinkingLevel,
    memoryEnabled,
    kernelClient,
    allowHomeProject,
    autoPromote,
    userMemoriesEnabled,
    onPublished,
