function registerCtxFlushCommand(pi, deps) {
  pi.registerCommand("ctx-flush", {
    description: "Force pending Magic Context drops to materialize on the next provider call",
    handler: async (_args, ctx) => {
      const sessionId = resolveSessionId(ctx);
      if (!sessionId) {
        sendCtxStatusMessage(pi, {
          title: "/ctx-flush",
          text: `## /ctx-flush

No active Pi session is available.`,
          level: "error"
        });
        return;
      }
      if (deps.compactionOff) {
        sendCtxStatusMessage(pi, {
          title: "/ctx-flush",
          text: COMPACTION_OFF_COMMAND_UNAVAILABLE,
          level: "warning"
        });
        return;
      }
      const pendingBefore = getPendingOps(deps.db, sessionId).length;
      const result = executeFlush(deps.db, sessionId);
      signalPiHistoryRefresh(sessionId);
      signalPiPendingMaterialization(sessionId);
      signalPiSystemPromptRefresh(sessionId);
      const text = pendingBefore > 0 ? `## /ctx-flush

Flushed ${pendingBefore} pending ops; next provider call will materialize.

${result}` : `## /ctx-flush

${result}`;
      sendCtxStatusMessage(pi, {
        title: "/ctx-flush",
        text,
        level: result.startsWith("Error:") ? "error" : "success"
      }, { sessionId, pendingBefore, result });
    }
  });
}

