function inferLevel(text) {
  const lower = text.toLowerCase();
  if (lower.includes("failed") || lower.includes("error"))
    return "error";
  if (lower.includes("confirmation") || lower.includes("⚠️"))
    return "warning";
  if (lower.includes("complete"))
    return "success";
  return "info";
}

