      db: deps.db,
      sessionId,
      mode: "manual-wrapup",
      contextLimit,
      executeThresholdPercentage,
      usage: { percentage: 0, inputTokens: 0 },
      usageSource: "manual-none",
      providerShapeVersion: "pi-folded-v1",
      cacheNamespace: `pi:${sessionId}`,
      messagesToKeep
